'use strict';
const portAreas=[{name:'Jacksonville',lat:30.40,lon:-81.53,vessel:'Atlantic Pioneer'},{name:'Miami',lat:25.77,lon:-80.17,vessel:'Harbor Sentinel'},{name:'Savannah',lat:32.12,lon:-81.14,vessel:'Coastal Surveyor'}];
let mapBounds=[-92,16,-65,37],selectedPort='Jacksonville',restoreCandidate=null;
function decisionBoard(){const high=open().filter(x=>['Critical','High'].includes(x.severity));return `<section class="panel decision-board"><div class="panel-top"><div><div class="eyebrow">PRIORITY BOARD</div><h2>What needs a decision?</h2></div><a href="#reports">Management reports →</a></div><div class="steps"><a class="decision" href="#incidents"><b>${high.length}</b><span>High-priority open incidents</span><small>Assign an owner and confirm next action</small></a><a class="decision" href="#maintenance"><b>${overdue().length}</b><span>Overdue maintenance tasks</span><small>Resolve the sample follow-up queue</small></a><a class="decision" href="#map"><b>${portAreas.length}</b><span>Reference port areas</span><small>Open the fleet operating map</small></a></div></section>`}
function fleetMap(){return head('FLEET OPERATING MAP','A geographic view of the scenario.','Explore approximate port reference areas and fictional fleet assignments. Coastlines are stored locally; no external map service is contacted.')+`<section class="panel map-panel"><div class="panel-top"><h2>Atlantic operations</h2><span class="badge">AIS not connected</span></div><div class="toolbar"><select id="map-vessel" aria-label="Filter map by vessel"><option>All sample vessels</option>${vessels.map(v=>`<option>${e(v.name)}</option>`).join('')}</select><button data-map="atlantic" class="quiet">US Atlantic</button><button data-map="world" class="quiet">World</button><button data-map="in" class="quiet" aria-label="Zoom map in">+</button><button data-map="out" class="quiet" aria-label="Zoom map out">−</button></div><div id="operating-map" aria-label="Interactive reference port map"></div><div class="map-bottom"><span><i></i> Reference port area · Not a vessel position</span><div class="actions"><button data-map="west" aria-label="Pan map west">←</button><button data-map="north" aria-label="Pan map north">↑</button><button data-map="south" aria-label="Pan map south">↓</button><button data-map="east" aria-label="Pan map east">→</button></div></div><p class="source">Natural Earth · Public domain · Approximate schematic coastline, not a nautical chart.</p></section><div class="two"><section class="panel" id="map-selection"></section><section class="panel"><div class="eyebrow">REAL-TIME POSITION SERVICE</div><h2>AIS connection required</h2><div class="status-row"><span>Provider</span><span>Not configured</span></div><div class="status-row"><span>Last AIS message</span><span>None received</span></div><div class="status-row"><span>Live vessels</span><span>0 verified</span></div><p class="muted">Real positions require a provider, a secure server connection, vessel identification and timestamps. Missing or stale data must remain visible to the operator.</p><a href="#pilot">Include AIS in the pilot scope →</a></section></div>`}
function drawMap(){if(!$('operating-map'))return;const [west,south,east,north]=mapBounds,W=1000,H=540,xy=([lon,lat])=>[(lon-west)/(east-west)*W,(north-lat)/(north-south)*H];
const paths=oceanLand.filter(r=>r.some(([x,y])=>x>=west-8&&x<=east+8&&y>=south-8&&y<=north+8)).map(r=>'M'+r.map(c=>xy(c).map(n=>n.toFixed(1)).join(',')).join('L')+'Z').join('');
const filter=$('map-vessel').value;const points=portAreas.filter(p=>filter==='All sample vessels'||p.vessel===filter);if(!points.some(p=>p.name===selectedPort))selectedPort=points[0]?.name||'Jacksonville';
let grid='';const lonStep=(east-west)>100?30:5,latStep=(north-south)>70?30:5;for(let lon=Math.ceil(west/lonStep)*lonStep;lon<east;lon+=lonStep){const [x]=xy([lon,south]);grid+=`<path d="M${x} 0V${H}"/><text x="${x+5}" y="${H-10}">${Math.abs(lon)}°${lon<0?'W':'E'}</text>`}for(let lat=Math.ceil(south/latStep)*latStep;lat<north;lat+=latStep){const [,y]=xy([west,lat]);grid+=`<path d="M0 ${y}H${W}"/><text x="8" y="${y-7}">${Math.abs(lat)}°${lat<0?'S':'N'}</text>`}
$('operating-map').innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="group" aria-label="Reference ports. Use the labeled port buttons or map controls."><defs><clipPath id="mapClip"><rect width="1000" height="540"/></clipPath></defs><rect width="1000" height="540" fill="#061a32"/><g class="map-grid">${grid}</g><g clip-path="url(#mapClip)"><path class="map-land" d="${paths}"/>${points.map(p=>{const [x,y]=xy([p.lon,p.lat]);return `<g role="button" tabindex="0" data-port="${p.name}" aria-label="Select ${p.name} reference port" class="map-marker${p.name===selectedPort?' selected':''}" transform="translate(${x},${y})"><circle class="map-halo" r="18"/><circle r="6"/><text x="16" y="5">${p.name}</text></g>`}).join('')}</g><text class="map-watermark" x="980" y="25" text-anchor="end">REFERENCE AREAS · NOT LIVE TRACKING</text></svg>`;
const p=portAreas.find(p=>p.name===selectedPort),v=vessels.find(v=>v.name===p.vessel);$('map-selection').innerHTML=`<div class="eyebrow">SELECTED REFERENCE AREA</div><h2>${e(p.name)}</h2><p>Approximate area: ${p.lat.toFixed(2)}° N, ${Math.abs(p.lon).toFixed(2)}° W</p><div class="status-row"><span>Fictional vessel assignment</span><strong>${e(v.name)}</strong></div><div class="status-row"><span>Sample vessel status</span>${badge(v.status)}</div><div class="status-row"><span>Reported speed / course</span><span>Unavailable</span></div><div class="port-buttons">${portAreas.map(p=>`<button data-port="${p.name}" class="quiet">${p.name}</button>`).join('')}</div><p class="source">These coordinates identify reference areas, not current positions of the sample vessels.</p>`}
function moveMap(action){let [w,s,e,n]=mapBounds,dx=e-w,dy=n-s,cx=(w+e)/2,cy=(s+n)/2;if(action==='world')mapBounds=[-180,-75,180,85];else if(action==='atlantic')mapBounds=[-92,16,-65,37];else{if(action==='in'){dx=Math.max(6,dx*.65);dy=Math.max(4,dy*.65)}if(action==='out'){dx=Math.min(360,dx/0.65);dy=Math.min(160,dy/0.65)}if(action==='west')cx-=dx*.2;if(action==='east')cx+=dx*.2;if(action==='north')cy+=dy*.2;if(action==='south')cy-=dy*.2;cx=Math.min(180-dx/2,Math.max(-180+dx/2,cx));cy=Math.min(85-dy/2,Math.max(-85+dy/2,cy));mapBounds=[cx-dx/2,cy-dy/2,cx+dx/2,cy+dy/2]}drawMap()}
function choosePort(name){const p=portAreas.find(p=>p.name===name);if(!p)return;selectedPort=name;$('map-vessel').value='All sample vessels';mapBounds=[p.lon-9,p.lat-7,p.lon+9,p.lat+7];drawMap()}
function csvCell(v){let t=String(v??'');if(/^[\s\u0000-\u001f]*[=+@-]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"'}
function exportCsv(kind){const records={fleet:vessels,assets,incidents:data.incidents,tasks:data.tasks}[kind];if(!records?.length){toast('No records to export.');return}const headers=Object.keys(records[0]);const out=[headers.map(csvCell).join(','),...records.map(r=>headers.map(k=>csvCell(r[k])).join(','))].join('\r\n');download('OceanCentinell-'+kind+'-DEMO.csv','text/csv','\ufeff'+out)}
function previewRestore(text){try{if(text.length>2*1024*1024)throw Error();const v=JSON.parse(text);if(v.app!=='OceanCentinell Business Demo'||v.version!==1||!valid(v.data))throw Error();restoreCandidate=structuredClone(v.data);$('restoreSummary').textContent=`Validated backup: ${v.data.incidents.length} incidents, ${v.data.tasks.length} maintenance tasks and one pilot draft.`;$('restoreDialog').showModal()}catch{restoreCandidate=null;toast('This is not a valid OceanCentinell demonstration backup. Existing records were preserved.')}}
document.addEventListener('click',ev=>{const m=ev.target.closest('[data-map]');if(m)moveMap(m.dataset.map);const p=ev.target.closest('[data-port]');if(p)choosePort(p.dataset.port);const a=ev.target.closest('[data-action]')?.dataset.action;if(a?.startsWith('csv-'))exportCsv(a.slice(4));if(a==='restore'){if(window.CentinellDevice?.importBackup)window.CentinellDevice.importBackup();else $('backupFile').click()}});
document.addEventListener('keydown',ev=>{const p=ev.target.closest('[data-port]');if(p&&['Enter',' '].includes(ev.key)){ev.preventDefault();choosePort(p.dataset.port)}});
document.getElementById('backupFile').addEventListener('change',async ev=>{const f=ev.target.files[0];if(f){if(f.size>2*1024*1024)toast('Backup exceeds the 2 MB limit.');else previewRestore(await f.text())}ev.target.value=''});
document.getElementById('cancelRestore').onclick=()=>{restoreCandidate=null;$('restoreDialog').close()};
document.getElementById('confirmRestore').onclick=()=>{if(!restoreCandidate)return;const oldError=storageError;storageError=false;if(commit(restoreCandidate)){restoreCandidate=null;$('restoreDialog').close();toast('Validated demonstration backup restored locally.')}else storageError=oldError};
